Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='failuresaretodos', at=datetime(2026, 10, 25, 0, 0, 0), actor='owner', title='A persistent failure files a todo on the project chain that an agent can fix', body='A failure that persists (a source failing for a day, a red nightly gate, a check that keeps refusing) files a todo on the suzatary chain, once per failure episode, priced by its class and duration. A card is kept only for what the owner alone can do, such as a sign-in or a consent, and the todo names the card. The two are different audiences, not duplicates.', rationale='The owner, 2026-10-25: the todo should be on the project chain, so an agent can fix it and pick up the most important tasks first.', supersedes=()))